29|inline U load_vector(const device T* x, thread U* x_thread) {
30|  static_assert(
31|      bits == 1 || bits == 2 || bits == 3 || bits == 4 || bits == 5 ||
32|          bits == 6 || bits == 8,
33|      "Template undefined for bits not in {1, 2, 3, 4, 5, 6, 8}");
34|
35|  U sum = 0;
36|
37|  if (bits == 1) {
38|    for (int i = 0; i < values_per_thread; i += 8) {
39|      sum += x[i] + x[i + 1] + x[i + 2] + x[i + 3] + x[i + 4] + x[i + 5] +
40|          x[i + 6] + x[i + 7];
41|      x_thread[i] = x[i];
42|      x_thread[i + 1] = x[i + 1];
43|      x_thread[i + 2] = x[i + 2];
44|      x_thread[i + 3] = x[i + 3];
45|      x_thread[i + 4] = x[i + 4];
