47|      x_thread[i + 6] = x[i + 6];
48|      x_thread[i + 7] = x[i + 7];
49|    }
50|  }
51|
52|  else if (bits == 2) {
53|    for (int i = 0; i < values_per_thread; i += 4) {
54|      sum += U(x[i]) + U(x[i + 1]) + U(x[i + 2]) + U(x[i + 3]);
55|      x_thread[i] = x[i];
56|      x_thread[i + 1] = x[i + 1] / 4.0f;
57|      x_thread[i + 2] = x[i + 2] / 16.0f;
58|      x_thread[i + 3] = x[i + 3] / 64.0f;
59|    }
60|  }
