70|      x_thread[i + 4] = x[i + 4] / 16.0f;
71|      x_thread[i + 5] = x[i + 5] / 128.0f;
72|      x_thread[i + 6] = x[i + 6] / 4.0f;
73|      x_thread[i + 7] = x[i + 7] / 32.0f;
74|    }
75|  }
76|
77|  else if (bits == 4) {
78|    for (int i = 0; i < values_per_thread; i += 4) {
79|      sum += U(x[i]) + U(x[i + 1]) + U(x[i + 2]) + U(x[i + 3]);
