221|template <typename U, int values_per_thread, int bits>
222|inline U qdot(
223|    const device uint8_t* w,
224|    const thread U* x_thread,
225|    U scale,
226|    U bias,
227|    U sum) {
228|  static_assert(
229|      bits == 1 || bits == 2 || bits == 3 || bits == 4 || bits == 5 ||
230|          bits == 6 || bits == 8,
231|      "Template undefined for bits not in {1, 2, 3, 4, 5, 6, 8}");
232|
233|  U accum = 0;
234|
235|  if (bits == 1) {
236|    for (int i = 0; i < (values_per_thread / 8); i++) {
237|      uint8_t wb = w[i];
238|      accum += select(U(0), x_thread[8 * i], bool(wb & 0x01));
239|      accum += select(U(0), x_thread[8 * i + 1], bool(wb & 0x02));
240|      accum += select(U(0), x_thread[8 * i + 2], bool(wb & 0x04));
241|      accum += select(U(0), x_thread[8 * i + 3], bool(wb & 0x08));
242|      accum += select(U(0), x_thread[8 * i + 4], bool(wb & 0x10));
243|      accum += select(U(0), x_thread[8 * i + 5], bool(wb & 0x20));
244|      accum += select(U(0), x_thread[8 * i + 6], bool(wb & 0x40));
245|      accum += select(U(0), x_thread[8 * i + 7], bool(wb & 0x80));
246|    }
247|  }
248|
249|  else if (bits == 2) {
250|    for (int i = 0; i < (values_per_thread / 4); i++) {
251|      accum +=
252|          (x_thread[4 * i] * (w[i] & 0x03) +
253|           x_thread[4 * i + 1] * (w[i] & 0x0c) +
254|           x_thread[4 * i + 2] * (w[i] & 0x30) +
255|           x_thread[4 * i + 3] * (w[i] & 0xc0));
256|    }
257|  }
258|
259|  else if (bits == 3) {
260|    for (int i = 0; i < (values_per_thread / 8); i++) {
261|      x_thread += 8 * i;
262|      w += 3 * i;
263|
264|      accum += (w[0] & 0x07) * x_thread[0];
265|      accum += (w[0] & 0x38) * x_thread[1];
266|      accum += (w[0] & 0xc0) * x_thread[2];
267|      accum += (w[1] & 0x01) * (x_thread[2] * 256.0f);
268|
269|      accum += (w[1] & 0x0e) * x_thread[3];
270|      accum += (w[1] & 0x70) * x_thread[4];
271|      accum += (w[1] & 0x80) * x_thread[5];
272|      accum += (w[2] & 0x03) * (x_thread[5] * 256.0f);
273|
274|      accum += (w[2] & 0x1c) * x_thread[6];
275|      accum += (w[2] & 0xe0) * x_thread[7];
276|    }
277|  }
278|
279|  else if (bits == 4) {
280|    const device uint16_t* ws = (const device uint16_t*)w;
281|    for (int i = 0; i < (values_per_thread / 4); i++) {
282|      accum +=
283|          (x_thread[4 * i] * (ws[i] & 0x000f) +
284|           x_thread[4 * i + 1] * (ws[i] & 0x00f0) +
285|           x_thread[4 * i + 2] * (ws[i] & 0x0f00) +
286|           x_thread[4 * i + 3] * (ws[i] & 0xf000));
287|    }
288|  }
289|
290|  else if (bits == 5) {
291|    for (int i = 0; i < (values_per_thread / 8); i++) {
292|      x_thread += 8 * i;
293|      w += 5 * i;
294|
295|      accum += (w[0] & 0x1f) * x_thread[0];
296|      accum += (w[0] & 0xe0) * x_thread[1];
297|      accum += (w[1] & 0x3) * (x_thread[1] * 256.0f);
298|      accum += (w[1] & 0x7c) * x_thread[2];
299|      accum += (w[1] & 0x80) * x_thread[3];
300|      accum += (w[2] & 0xf) * (x_thread[3] * 256.0f);
301|      accum += (w[2] & 0xf0) * x_thread[4];
302|      accum += (w[3] & 0x1) * (x_thread[4] * 256.0f);
303|      accum += (w[3] & 0x3e) * x_thread[5];
304|      accum += (w[3] & 0xc0) * x_thread[6];
305|      accum += (w[4] & 0x7) * (x_thread[6] * 256.0f);
306|      accum += (w[4] & 0xf8) * x_thread[7];
307|    }
308|  }
309|
310|  else if (bits == 6) {
311|    for (int i = 0; i < (values_per_thread / 4); i++) {
312|      x_thread += 4 * i;
313|      w += 3 * i;
314|
315|      accum += (w[0] & 0x3f) * x_thread[0];
316|
317|      accum += (w[0] & 0xc0) * x_thread[1];
318|      accum += (w[1] & 0x0f) * (x_thread[1] * 256.0f);
319|
320|      accum += (w[1] & 0xf0) * x_thread[2];
321|      accum += (w[2] & 0x03) * (x_thread[2] * 256.0f);
322|
323|      accum += (w[2] & 0xfc) * x_thread[3];
324|    }
325|  }
326|
327|  else if (bits == 8) {
328|    for (int i = 0; i < values_per_thread; i++) {
329|      accum += x_thread[i] * w[i];
330|    }
331|  }
332|
333|  return scale * accum + sum * bias;
