452|template <typename U, int values_per_thread, int bits>
453|inline void
454|qouter(const thread uint8_t* w, U x, U scale, U bias, thread U* result) {
455|  static_assert(
456|      bits == 1 || bits == 2 || bits == 3 || bits == 4 || bits == 5 ||
457|          bits == 6 || bits == 8,
458|      "Template undefined for bits not in {1, 2, 3, 4, 5, 6, 8}");
459|
460|  if (bits == 1) {
461|    for (int i = 0; i < (values_per_thread / 8); i++) {
462|      uint8_t wb = w[i];
463|      result[8 * i] += x * (select(U(0), scale, bool(wb & 0x01)) + bias);
464|      result[8 * i + 1] += x * (select(U(0), scale, bool(wb & 0x02)) + bias);
465|      result[8 * i + 2] += x * (select(U(0), scale, bool(wb & 0x04)) + bias);
466|      result[8 * i + 3] += x * (select(U(0), scale, bool(wb & 0x08)) + bias);
